// Truncated JPEG (Ends prematurely)
const truncatedJpeg = validJpeg.slice(0, Math.floor(validJpeg.length / 2));
fs.writeFileSync(path.join(fixtureDir, 'truncated.jpg'), truncatedJpeg);

// Fake Extension (PNG saved as JPG)
fs.writeFileSync(path.join(fixtureDir, 'fake-ext.jpg'), validPng);

// Invalid JPEG Marker Length (Modifying APP0 length to be artificially large to trigger bounding/crash checks)
const maliciousJpeg = Buffer.from(validJpeg);
// Length is at bytes [4,5], normally 0x00 0x10. We change it to 0xFF 0xFF
maliciousJpeg[4] = 0xFF;
maliciousJpeg[5] = 0xFF;
fs.writeFileSync(path.join(fixtureDir, 'malformed-length.jpg'), maliciousJpeg);

console.log('Fixtures generated successfully.');
